// QA-005: prove Node's built-in zlib is loadable inside the n8n Code-node sandbox and round-trips.
// Without NODE_FUNCTION_ALLOW_BUILTIN=zlib the require() throws ('Module zlib is disallowed') and execution
// exits non-zero (the negative control). With it set, we additionally THROW if the round trip is wrong, so the
// execute exit code alone is a reliable PASS/FAIL signal (no fragile stdout parsing).
var zlib = require('zlib');
var input = 'marketing-scout-zlib-roundtrip-' + Array(200).join('AB');
var buf = Buffer.from(input, 'utf8');
var compressed = zlib.deflateSync(buf);
var decompressed = zlib.inflateSync(compressed).toString('utf8');
if (decompressed !== input) { throw new Error('ZLIB_ROUNDTRIP_FAIL'); }
return [{ json: {
  zlib_loaded: true,
  round_trip_ok: true,
  original_bytes: buf.length,
  compressed_bytes: compressed.length
} }];
